Tutor.registerIndex("hist-adult", [
{"id":"hist-a-korea-01","kind":"unit","title":"선사 시대와 고조선, 여러 나라","text":"구석기부터 철기 시대까지의 생활 모습과 고조선의 건국·발전·멸망, 그리고 부여·고구려·옥저·동예·삼한의 정치와 풍습을 시대 순서대로 정리합니다. 구석기·신석기·청동기·철기 시대의 도구와 생활 모습을 비교할 수 있다. 고조선의 건국 이야기, 8조법, 위만 조선의 성격과 멸망 과정을 설명할 수 있다. 부여·고구려·옥저·동예·삼한의 정치 구조와 대표 풍습을 구…","keywords":["선사 시대","뗀석기","간석기","빗살무늬 토기","고인돌","비파형 동검","8조법","제정일치","사출도","소도"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#c0","kind":"concept","title":"구석기 시대와 신석기 시대","text":"역사를 문자 기록의 유무로 나누면, 기록이 없는 때를 선사 시대라고 합니다. 선사 시대는 쓰던 도구의 재료와 만드는 방법에 따라 나눕니다. 구분 · 구석기 시대 · 신석기 시대 시작 (한반도) · 약 70만 년 전 · 기원전 8000년경 대표 도구 · 뗀석기(주먹도끼, 찍개, 긁개, 슴","keywords":["선사 시대","뗀석기","간석기","빗살무늬 토기"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#c1","kind":"concept","title":"청동기 시대와 철기 시대","text":"청동기 시대(한반도와 만주, 기원전 2000년~기원전 1500년경 시작)에는 구리에 주석을 섞은 청동으로 무기와 장신구를 만들었습니다. 청동은 귀해서 주로 지배자가 썼고, 농기구는 여전히 돌로 만들었습니다(반달 돌칼 등). 대표 유물: 비파형 동검, 거친무늬 거울, 민무늬 토기, 반달 ","keywords":["고인돌","비파형 동검"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#c2","kind":"concept","title":"고조선의 건국과 발전","text":"고조선은 우리 역사에서 처음 세워진 나라입니다. 『삼국유사』 등에 전하는 단군 건국 이야기에 따르면 기원전 2333년에 단군왕검이 세웠다고 합니다. 건국 이야기에는 당시 사회의 모습이 담겨 있습니다. 이야기 속 내용 · 알 수 있는 점 하늘신의 아들 환웅이 무리를 이끌고 내려옴 · 하늘","keywords":["고인돌","비파형 동검","제정일치"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#c3","kind":"concept","title":"8조법, 위만 조선과 고조선의 멸망","text":"고조선에는 사회 질서를 지키는 8조법(범금 8조)이 있었습니다. 지금은 세 조항만 전합니다. 사람을 죽인 자는 즉시 사형에 처한다. → 생명을 중시함 남에게 상처를 입힌 자는 곡식으로 갚는다. → 농경 사회, 노동력 중시 남의 물건을 훔친 자는 그 집의 노비로 삼는다. 용서받으려면 50","keywords":["8조법"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#c4","kind":"concept","title":"부여와 고구려","text":"고조선 무렵과 그 뒤에 만주와 한반도 곳곳에서 철기 문화를 바탕으로 여러 나라가 일어났습니다. 부여 — 만주 쑹화강 유역의 넓은 평야에서 농경과 목축을 하였습니다. 정치: 왕 아래 마가·우가·저가·구가(가축 이름을 딴 관리)가 각자 사출도를 다스린 연맹 왕국입니다. 왕권이 약해 가뭄이나","keywords":["사출도"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#c5","kind":"concept","title":"옥저·동예와 삼한","text":"옥저와 동예 — 함경도와 강원도 북부의 동해안에 있었습니다. 고구려의 압박을 받아 왕이 없이 읍군·삼로라는 군장이 각자 자기 부족을 다스렸고, 고구려에 소금과 해산물 등을 바쳤습니다. 나라 · 대표 풍습·특산물 옥저 · 어린 여자아이를 신랑 집에서 기르다가 어른이 되면 혼인시키는 민며느","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t0","kind":"term","title":"선사 시대","text":"문자로 남긴 기록이 없는 시대입니다. 구석기·신석기 시대가 여기에 속하며, 유물과 유적으로 생활을 짐작합니다.","keywords":["선사 시대"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t1","kind":"term","title":"뗀석기","text":"돌을 깨뜨리거나 떼어 내어 만든 구석기 시대의 도구입니다. 예: 주먹도끼, 찍개, 슴베찌르개","keywords":["뗀석기"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t2","kind":"term","title":"간석기","text":"돌을 갈아서 만든 신석기 시대의 정교한 도구입니다. 예: 돌보습, 갈돌과 갈판","keywords":["간석기"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t3","kind":"term","title":"빗살무늬 토기","text":"겉면에 빗살 같은 무늬를 새긴 신석기 시대의 대표 토기입니다. 곡식 저장과 조리에 썼습니다.","keywords":["빗살무늬 토기"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t4","kind":"term","title":"고인돌","text":"청동기 시대 지배자(군장)의 무덤입니다. 큰 덮개돌을 옮기는 데 많은 사람이 필요했으므로 지배자의 힘을 보여 줍니다.","keywords":["고인돌"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t5","kind":"term","title":"비파형 동검","text":"악기 비파처럼 생긴 청동기 시대의 칼입니다. 고조선의 문화 범위를 짐작하게 해 줍니다.","keywords":["비파형 동검"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t6","kind":"term","title":"8조법","text":"고조선의 법으로, 세 조항이 전합니다. 생명 존중, 사유 재산 인정, 노비 신분의 존재를 알 수 있습니다.","keywords":["8조법"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t7","kind":"term","title":"제정일치","text":"제사장과 정치 지배자가 같은 사회입니다. 단군왕검(단군=제사장, 왕검=정치 지배자)이 대표적인 예입니다.","keywords":["제정일치"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t8","kind":"term","title":"사출도","text":"부여에서 마가·우가·저가·구가가 각자 다스린 지역입니다. 왕은 중앙만 직접 다스렸습니다.","keywords":["사출도"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#t9","kind":"term","title":"소도","text":"삼한에서 제사장인 천군이 다스린 신성한 지역입니다. 죄인이 들어가도 잡아갈 수 없어 제정 분리를 보여 줍니다.","keywords":["소도"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#f0","kind":"faq","title":"단군 이야기는 신화인데 역사로 배워도 되나요?","text":"곰이 사람이 되었다는 내용을 그대로 사실로 보지는 않습니다. 다만 건국 이야기에는 그 시대의 모습(이주 세력과 토착 세력의 연합, 농경 중시, 제정일치)이 상징적으로 담겨 있어 중요한 역사 자료가 됩니다. 『삼국유사』 같은 기록과 비파형 동검·고인돌 같은 유물을 함께 보며 고조선을 이해합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#f1","kind":"faq","title":"영고, 동맹, 무천이 자꾸 헷갈려요.","text":"시기와 나라를 묶어 외워 보세요. 부여는 12월 영고, 고구려는 10월 동맹, 동예는 10월 무천입니다. 삼한은 5월과 10월의 계절제입니다. 12월에 여는 것은 부여 하나뿐이라는 점을 먼저 기억하면 나머지가 정리됩니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#f2","kind":"faq","title":"비파형 동검과 세형 동검은 무엇이 다른가요?","text":"비파형 동검은 칼날 아래쪽이 비파처럼 불룩한 모양으로, 청동기 시대 고조선 문화권의 대표 유물입니다. 세형 동검은 칼날이 가늘고 곧은 모양으로, 철기 시대 초기에 한반도에서 만든 한국식 동검입니다. 세형 동검의 거푸집이 나와 우리 땅에서 직접 만들었음을 알 수 있습니다.","keywords":["비파형 동검"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#m0","kind":"mistake","title":"자주 하는 실수","text":"\"신석기 = 농경 시작, 청동기 = 벼농사 시작\"을 섞는 실수 — 농경 자체는 신석기 시대(조·피 등 잡곡)에, 벼농사는 청동기 시대에 시작되었습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#m1","kind":"mistake","title":"자주 하는 실수","text":"고조선을 제정 분리 사회로, 삼한을 제정일치 사회로 거꾸로 기억하는 실수 — 단군왕검은 제정일치, 천군과 소도가 있는 삼한은 제정 분리입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-01#m2","kind":"mistake","title":"자주 하는 실수","text":"청동기 시대에 청동 농기구를 썼다고 생각하는 실수 — 청동은 귀해서 무기·장신구·의식 도구로 쓰였고, 농기구는 반달 돌칼처럼 돌로 만들었습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-01","grade":"a"},
{"id":"hist-a-korea-02","kind":"unit","title":"삼국과 가야","text":"고구려·백제·신라·가야가 나라의 기틀을 다지고 경쟁한 과정을 왕별 업적과 문화유산 중심으로 정리합니다. 고구려·백제·신라의 주요 왕과 업적을 시기 순서대로 정리할 수 있다. 한강 유역을 둘러싼 삼국의 경쟁 흐름을 설명할 수 있다. 가야 연맹의 성장과 멸망 과정을 설명할 수 있다. 삼국의 고분·불상·탑과 일본으로의 문화 전파를 나라별로 구별할 수 있다.","keywords":["율령","태학","광개토 대왕릉비","22담로","마립간","화랑도","순수비","가야 연맹","굴식 돌방무덤","돌무지덧널무덤"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#c0","kind":"concept","title":"고구려의 발전: 소수림왕·광개토 대왕·장수왕","text":"고구려는 일찍부터 주변을 정복하며 성장하였지만, 4세기 중반 큰 위기를 맞았습니다. 백제 근초고왕의 공격으로 고국원왕이 평양성에서 전사(371)한 것입니다. 이 위기를 딛고 고구려는 체제를 다시 세웠습니다. 소수림왕(4세기 후반) — 나라의 기틀을 다졌습니다. 중국 전진에서 불교를 받아","keywords":["율령","태학"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#c1","kind":"concept","title":"백제의 발전: 근초고왕·무령왕·성왕","text":"백제는 한강 유역(한성)에서 출발해 마한의 여러 나라를 아우르며 성장하였습니다. 근초고왕(4세기 후반) — 백제의 전성기를 열었습니다. 남쪽으로 마한의 남은 지역을 정복하고, 북쪽으로 고구려의 평양성을 공격해 고국원왕을 전사시켰습니다(371). 바다 건너 중국의 동진, 일본의 왜와 교류","keywords":["22담로"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#c2","kind":"concept","title":"신라의 발전: 내물왕·지증왕·법흥왕·진흥왕","text":"신라는 경주 지역의 사로국에서 출발해 가장 늦게 중앙 집권 국가로 발전하였지만, 결국 한강을 차지하고 삼국 통일의 주인공이 됩니다. 내물왕(4세기 후반) — 김씨가 왕위를 이어받는 체제를 굳히고, 대군장이라는 뜻의 마립간이라는 칭호를 썼습니다. 왜가 쳐들어오자 고구려 광개토 대왕의 도움","keywords":["율령","마립간"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#c3","kind":"concept","title":"가야 연맹의 성장과 멸망","text":"낙동강 하류의 변한 지역에서는 여러 작은 나라가 모여 가야 연맹을 이루었습니다. 전기 가야 연맹 — 금관가야(김해) 중심 김수로가 세웠다고 전합니다. 이 지역은 철이 풍부하여 철제 무기와 갑옷을 만들고, 덩이쇠를 화폐처럼 쓰며 낙랑과 왜에 철을 수출하였습니다. 바닷가에 있어 해상 교역이","keywords":["가야 연맹"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#c4","kind":"concept","title":"삼국의 문화유산과 일본으로의 문화 전파","text":"고분(무덤) — 무덤 양식은 나라와 시기를 알려 주는 중요한 단서입니다. 나라 · 대표 무덤 양식 · 대표 유적 고구려 · 돌무지무덤 → 굴식 돌방무덤(벽화) · 장군총, 무용총(수렵도), 강서대묘(사신도) 백제 · 한성: 돌무지무덤 / 웅진: 벽돌무덤 / 사비: 굴식 돌방무덤 · 서울","keywords":["굴식 돌방무덤","돌무지덧널무덤"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t0","kind":"term","title":"율령","text":"형벌에 관한 법(율)과 행정에 관한 법(령)을 함께 이르는 말입니다. 율령 반포는 나라를 법으로 다스리는 체제를 갖추었다는 뜻입니다. 예: 고구려 소수림왕, 신라 법흥왕","keywords":["율령"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t1","kind":"term","title":"태학","text":"고구려 소수림왕 때 세운 국립 교육 기관으로, 유학을 가르쳤습니다.","keywords":["태학"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t2","kind":"term","title":"광개토 대왕릉비","text":"장수왕이 아버지 광개토 대왕의 업적을 기려 세운 비석입니다(414). 지금의 중국 지린성 지안에 있습니다.","keywords":["광개토 대왕릉비"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t3","kind":"term","title":"22담로","text":"백제의 지방 중심지 22곳입니다. 무령왕이 이곳에 왕족을 보내 지방을 다스렸습니다.","keywords":["22담로"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t4","kind":"term","title":"마립간","text":"\"대군장\"이라는 뜻의 신라 왕의 칭호입니다. 내물왕 때부터 쓰였고, 지증왕 때 \"왕\"으로 바뀌었습니다.","keywords":["마립간"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t5","kind":"term","title":"화랑도","text":"신라의 청소년 수련 단체입니다. 진흥왕 때 국가 조직으로 개편되어 인재를 길렀습니다.","keywords":["화랑도"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t6","kind":"term","title":"순수비","text":"왕이 새로 넓힌 땅을 돌아보고 세운 비석입니다. 신라 진흥왕의 북한산비·창녕비·황초령비·마운령비가 있습니다.","keywords":["순수비"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t7","kind":"term","title":"가야 연맹","text":"낙동강 하류의 변한 지역에서 여러 작은 나라가 이룬 연맹입니다. 전기는 금관가야, 후기는 대가야가 이끌었습니다.","keywords":["가야 연맹"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t8","kind":"term","title":"굴식 돌방무덤","text":"돌로 방을 만들고 입구와 통로를 낸 무덤입니다. 벽에 그림을 그릴 수 있었고 도굴되기 쉬웠습니다.","keywords":["굴식 돌방무덤"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#t9","kind":"term","title":"돌무지덧널무덤","text":"나무 덧널 위에 돌을 쌓고 흙으로 덮은 신라의 무덤입니다. 입구가 없어 도굴이 어려웠습니다.","keywords":["돌무지덧널무덤"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#f0","kind":"faq","title":"삼국의 전성기가 각각 언제인지 쉽게 외우는 법이 있나요?","text":"세기로 묶어 보세요. 4세기는 백제(근초고왕), 5세기는 고구려(광개토 대왕·장수왕), 6세기는 신라(진흥왕)입니다. 4·5·6세기에 백제 → 고구려 → 신라 순서로 전성기를 맞았고, 그때마다 한강 유역의 주인도 바뀌었습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#f1","kind":"faq","title":"율령을 반포했다는 게 왜 중요한가요?","text":"율령은 나라 전체에 똑같이 적용되는 법과 제도입니다. 율령을 반포했다는 것은 각 지역 세력이 제멋대로 다스리던 연맹 단계를 넘어, 왕이 법으로 나라 전체를 다스리는 중앙 집권 국가가 되었다는 뜻입니다. 고구려는 소수림왕, 신라는 법흥왕 때 율령을 반포하였고, 백제는 고이왕 때 율령을 정비했다고 전합니다.","keywords":["율령"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#f2","kind":"faq","title":"불교를 받아들인 것이 나라를 다스리는 데 어떤 도움이 되었나요?","text":"여러 부족이 각자 다른 신을 섬기던 상황에서, 불교는 모두가 함께 믿는 하나의 사상을 주었습니다. \"왕이 곧 부처\"라는 생각과 결합하여 왕의 권위를 높이는 데에도 쓰였습니다. 그래서 삼국은 모두 중앙 집권 체제를 갖추는 시기에 불교를 받아들였습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#m0","kind":"mistake","title":"자주 하는 실수","text":"광개토 대왕과 장수왕의 업적을 바꾸어 기억하는 실수 — 평양 천도(427)와 한성 함락(475)은 장수왕, 영락 연호와 신라 구원(400)은 광개토 대왕입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#m1","kind":"mistake","title":"자주 하는 실수","text":"법흥왕과 진흥왕이 병합한 가야를 바꾸는 실수 — 금관가야는 법흥왕(532), 대가야는 진흥왕(562)입니다. \"법금, 진대\"로 묶어 기억하세요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-02#m2","kind":"mistake","title":"자주 하는 실수","text":"근초고왕(백제)과 소수림왕(고구려)의 시기를 따로 기억하는 실수 — 근초고왕이 고국원왕을 전사시킨(371) 위기 직후에 소수림왕의 개혁(372~373)이 이어졌습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-02","grade":"a"},
{"id":"hist-a-korea-03","kind":"unit","title":"삼국 통일과 남북국 시대","text":"삼국 통일 과정과 통일 신라·발해의 발전, 신라 말 혼란에서 후삼국으로 이어지는 흐름을 정리합니다. 고구려와 수·당의 전쟁, 신라의 삼국 통일 과정을 순서대로 설명할 수 있다. 신문왕의 체제 정비와 신라 말의 사회 혼란을 설명할 수 있다. 발해의 건국과 발전 과정, 고구려 계승 의식을 설명할 수 있다. 통일 신라·발해의 문화유산과 호족의 성장, 후삼국의 …","keywords":["살수 대첩","안시성 싸움","나·당 전쟁","관료전","녹읍","9주 5소경","해동성국","남북국 시대","호족","6두품"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#c0","kind":"concept","title":"고구려와 수·당의 전쟁","text":"6세기 말 중국을 통일한 수는 동북아시아의 강자 고구려를 굴복시키려 하였습니다. 고구려는 이에 맞서 70여 년 동안 중국 왕조의 침략을 막아 냈습니다. 수와의 전쟁 수 문제가 침략하였으나(598) 실패하였습니다. 수 양제가 100만이 넘는 대군으로 쳐들어왔습니다(612). 고구려의 을지","keywords":["살수 대첩"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#c1","kind":"concept","title":"신라의 삼국 통일 과정","text":"7세기 중반 신라는 고구려와 백제의 협공으로 위기에 빠졌습니다. 백제 의자왕이 신라의 대야성을 빼앗자(642), 신라의 김춘추는 고구려에 도움을 청했다가 실패하고, 바다 건너 당과 군사 동맹(나·당 동맹, 648)을 맺었습니다. 1단계 — 백제 멸망(660) 김유신이 이끄는 신라군이 황","keywords":["나·당 전쟁"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#c2","kind":"concept","title":"통일 신라의 체제 정비와 신라 말의 혼란","text":"삼국 통일 뒤 신라는 늘어난 영토와 백성을 다스리기 위해 체제를 정비하고 왕권을 강화하였습니다. 무열왕(김춘추): 진골 출신으로 처음 왕위에 올랐고, 이후 그의 직계 자손이 왕위를 이었습니다. 신문왕: 통일 신라의 체제를 완성한 왕입니다. 장인 김흠돌의 반란을 진압하며 귀족 세력을 숙청","keywords":["관료전","녹읍","9주 5소경"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#c3","kind":"concept","title":"발해의 건국과 발전","text":"고구려가 멸망한 뒤 당은 고구려 유민을 요서 지방 등으로 강제로 옮겼습니다. 7세기 말 이 지역에서 당의 통제가 흔들리자, 고구려 장수 출신 대조영이 고구려 유민과 말갈인을 이끌고 동쪽으로 와서 동모산에서 발해를 세웠습니다(698). 왕 · 연호 · 주요 활동 무왕 · 인안 · 영토 확","keywords":["해동성국"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#c4","kind":"concept","title":"통일 신라와 발해의 문화","text":"통일 신라의 불교 문화 불국사: 부처의 나라를 땅 위에 나타내려 한 절입니다. 경내에 불국사 3층 석탑(석가탑)과 다보탑이 있습니다. 석가탑 안에서 현재 남아 있는 가장 오래된 목판 인쇄물 가운데 하나인 무구정광대다라니경이 나왔습니다. 석굴암: 돌을 다듬어 쌓아 만든 인공 석굴 사원으로","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#c5","kind":"concept","title":"호족의 성장과 후삼국의 성립","text":"신라 말 중앙 정치가 혼란에 빠지고 지방에 대한 통제가 약해지자, 지방에서 호족이라는 새로운 세력이 성장하였습니다. 호족: 지방에서 군사력과 경제력을 갖춘 세력입니다. 스스로 성주나 장군이라 부르며 자기 지역을 독자적으로 다스렸습니다. 지방의 촌주 출신, 중앙에서 밀려난 귀족, 바닷길 ","keywords":["호족","6두품"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t0","kind":"term","title":"살수 대첩","text":"612년 고구려의 을지문덕이 살수(청천강으로 봄)에서 수의 별동대를 크게 물리친 싸움입니다.","keywords":["살수 대첩"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t1","kind":"term","title":"안시성 싸움","text":"645년 당 태종이 이끄는 당군을 고구려 안시성의 군사와 백성이 힘을 합쳐 물리친 싸움입니다.","keywords":["안시성 싸움"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t2","kind":"term","title":"나·당 전쟁","text":"삼국 통일 뒤 한반도를 지배하려던 당에 맞서 신라가 벌인 전쟁입니다. 매소성(675)·기벌포(676) 승리로 당을 몰아냈습니다.","keywords":["나·당 전쟁"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t3","kind":"term","title":"관료전","text":"통일 신라 신문왕이 관리에게 준 땅으로, 그 땅에서 세금만 거둘 수 있었습니다(687).","keywords":["관료전"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t4","kind":"term","title":"녹읍","text":"귀족이 세금과 함께 그 땅 백성의 노동력까지 거둘 수 있던 땅입니다. 신문왕이 폐지했으나(689) 신라 말에 다시 생겼습니다.","keywords":["녹읍"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t5","kind":"term","title":"9주 5소경","text":"통일 신라의 지방 제도입니다. 전국을 9주로 나누고, 수도가 동남쪽에 치우친 점을 보완하려고 5소경을 두었습니다.","keywords":["9주 5소경"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t6","kind":"term","title":"해동성국","text":"\"바다 동쪽의 번성한 나라\"라는 뜻으로, 중국이 전성기(선왕 때)의 발해를 부른 이름입니다.","keywords":["해동성국"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t7","kind":"term","title":"남북국 시대","text":"남쪽의 통일 신라와 북쪽의 발해가 함께 있던 시기입니다.","keywords":["남북국 시대"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t8","kind":"term","title":"호족","text":"신라 말 지방에서 군사력과 경제력을 갖추고 성주·장군을 자칭하며 독자적으로 지역을 다스린 세력입니다.","keywords":["호족"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#t9","kind":"term","title":"6두품","text":"신라 골품제에서 진골 아래의 신분입니다. 학문과 능력이 있어도 높은 관직에 오를 수 없어 신라 말 개혁을 요구하였습니다. 예: 최치원","keywords":["6두품"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#f0","kind":"faq","title":"발해를 왜 우리 역사로 보나요?","text":"발해는 고구려 장수 출신 대조영이 고구려 유민과 함께 세웠고, 지배층의 중심이 고구려인이었습니다. 일본에 보낸 국서에서 스스로를 \"고려\"라 하였고, 온돌·무덤 양식·불상 등 문화에서도 고구려의 전통이 이어졌습니다. 이런 근거로 발해를 고구려를 계승한 우리 역사로 보며, 통일 신라와 함께 남북국 시대를 이루었다고 이해합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#f1","kind":"faq","title":"원효의 화쟁 사상과 의상의 화엄 사상이 자꾸 헷갈려요.","text":"\"쟁(爭)\"은 다툼이라는 뜻입니다. 화쟁은 \"다툼을 조화시킨다\", 곧 서로 다른 불교 주장을 하나로 조화시키려 한 원효의 사상입니다. 화엄은 의상이 당에서 공부해 온 화엄종의 사상으로, 모든 존재가 서로 의존하며 하나로 어우러진다는 내용입니다. 원효 = 화쟁·일심·대중화, 의상 = 화엄·부석사로 묶어 기억하세요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#f2","kind":"faq","title":"녹읍과 관료전은 무엇이 다른가요?","text":"두 가지 모두 관리나 귀족에게 준 땅이지만, 녹읍은 세금과 함께 그 땅 백성의 노동력까지 거둘 수 있었고 관료전은 세금만 거둘 수 있었습니다. 그래서 녹읍을 없애고 관료전을 준 신문왕의 정책은 귀족의 힘을 줄이고 왕권을 강화한 것으로 평가합니다.","keywords":["관료전","녹읍"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#m0","kind":"mistake","title":"자주 하는 실수","text":"살수 대첩과 안시성 싸움의 상대를 바꾸는 실수 — 살수 대첩(612)은 수, 안시성 싸움(645)은 당과의 싸움입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#m1","kind":"mistake","title":"자주 하는 실수","text":"신라의 삼국 통일을 고구려 멸망(668)으로 끝났다고 보는 실수 — 통일이 완성된 것은 나·당 전쟁에서 이긴 676년입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-03#m2","kind":"mistake","title":"자주 하는 실수","text":"발해 무왕과 문왕의 대외 정책을 바꾸는 실수 — 무왕은 당과 대립(산둥 공격), 문왕은 당과 친선(3성 6부 수용)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-03","grade":"a"},
{"id":"hist-a-korea-04","kind":"unit","title":"고려 시대","text":"후삼국 통일부터 고려의 멸망까지 정치 변화와 대외 관계, 대표 문화유산을 시기별로 정리합니다. 태조·광종·성종의 정책과 2성 6부를 중심으로 한 통치 체제를 설명할 수 있다. 문벌 귀족 사회의 동요와 무신 정권의 성립·전개를 설명할 수 있다. 거란·여진·몽골과의 관계와 항쟁, 원 간섭기와 공민왕의 개혁을 순서대로 정리할 수 있다. 팔만대장경·상감 청자·『…","keywords":["사심관 제도","기인 제도","노비안검법","2성 6부","음서","교정도감","삼별초","권문세족","신진 사대부","상감 기법"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#c0","kind":"concept","title":"고려의 건국과 태조·광종·성종","text":"왕건은 918년 고려를 세우고 이듬해 도읍을 자신의 근거지인 개경(송악)으로 옮겼습니다. 935년 신라 경순왕의 항복을 받아들이고, 936년 후백제를 무너뜨려 후삼국을 통일하였습니다. 거란에 멸망한 발해의 유민도 받아들여, 민족의 재통일이라는 의미를 갖습니다. 태조(왕건) — 호족을 끌","keywords":["기인 제도"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#c1","kind":"concept","title":"고려의 통치 체제","text":"고려는 당의 제도를 받아들이면서도 고려의 실정에 맞는 독자적인 기구를 두었습니다. 기구 · 하는 일 중서문하성 · 최고 관서. 장관인 문하시중이 국정을 총괄, 정책 심의·결정 상서성 · 6부(이·병·호·형·예·공부)를 거느리고 정책 집행 중추원 · 군사 기밀과 왕명 출납 어사대 · 관리","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#c2","kind":"concept","title":"문벌 귀족 사회와 무신 정권","text":"문벌 귀족: 고려 전기에는 여러 대에 걸쳐 고위 관리를 낸 가문이 음서와 공음전(자손에게 물려줄 수 있는 땅)으로 특권을 누렸습니다. 이들은 왕실과 혼인하며 권력을 키웠습니다. 문벌 귀족 사회의 동요 이자겸의 난(1126): 왕실과 거듭 혼인한 외척 이자겸이 권력을 휘두르다 반란을 일으","keywords":["음서"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#c3","kind":"concept","title":"거란·여진·몽골과의 관계와 항쟁","text":"거란의 침입 1차(993): 거란의 소손녕이 쳐들어오자, 서희가 외교 담판으로 고려가 고구려를 계승한 나라임을 내세워 강동 6주를 얻었습니다. 2차(1010): 강조의 정변을 구실로 쳐들어와 개경이 함락되었으나, 양규 등의 활약으로 물리쳤습니다. 3차(1018): 소배압이 쳐들어오자 강","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#c4","kind":"concept","title":"원 간섭기와 공민왕의 개혁, 고려의 멸망","text":"원 간섭기 — 몽골(원)과 강화한 뒤 고려는 80여 년 동안 원의 간섭을 받았습니다. 고려 왕은 원의 공주와 혼인하여 원의 부마국(사위 나라)이 되었고, 왕의 이름에 원에 대한 충성을 뜻하는 \"충\" 자가 붙었습니다(충렬왕, 충선왕 …). 관제가 격하되어 2성은 첨의부, 6부는 4사로 바","keywords":["권문세족"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#c5","kind":"concept","title":"고려의 문화: 불교·유학과 문화유산","text":"불교 — 고려는 불교를 크게 받들었습니다(연등회·팔관회). 의천(11세기): 교종을 중심으로 선종을 통합하려고 천태종을 열었고, 이론(교)과 수행(관)을 함께 닦자는 교관겸수를 내세웠습니다. 지눌(12세기 말~13세기 초): 불교계의 타락을 비판하며 수선사 결사를 이끌고, 선종을 중심으","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t0","kind":"term","title":"사심관 제도","text":"태조가 지방 출신 고위 관리를 그 지역의 사심관으로 삼아 지방의 일에 책임을 지게 한 제도입니다.","keywords":["사심관 제도"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t1","kind":"term","title":"기인 제도","text":"태조가 호족의 자제를 개경에 머물게 하여 볼모로 삼고 지방 일에 자문하게 한 제도입니다.","keywords":["기인 제도"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t2","kind":"term","title":"노비안검법","text":"광종이 억울하게 노비가 된 사람을 조사해 양인으로 되돌린 법입니다(956). 호족의 힘을 약화하였습니다.","keywords":["노비안검법"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t3","kind":"term","title":"2성 6부","text":"고려의 중앙 정치 조직입니다. 정책을 결정하는 중서문하성과 집행하는 상서성(2성), 상서성 아래의 6부로 이루어졌습니다.","keywords":["2성 6부"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t4","kind":"term","title":"음서","text":"왕족·공신이나 5품 이상 고위 관리의 자손을 시험 없이 관리로 뽑던 제도입니다.","keywords":["음서"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t5","kind":"term","title":"교정도감","text":"최충헌이 설치한 최씨 무신 정권의 최고 권력 기구입니다.","keywords":["교정도감"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t6","kind":"term","title":"삼별초","text":"최우 때 조직된 군사 조직으로, 개경 환도에 반대하여 강화도·진도·제주도에서 몽골에 맞서 싸웠습니다(1270~1273).","keywords":["삼별초"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t7","kind":"term","title":"권문세족","text":"원 간섭기에 원과 결탁하여 높은 관직과 넓은 농장을 차지한 지배 세력입니다.","keywords":["권문세족"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t8","kind":"term","title":"신진 사대부","text":"성리학을 공부하고 과거로 관직에 나간 고려 말의 새로운 세력입니다. 권문세족을 비판하며 개혁을 추구하였습니다.","keywords":["신진 사대부"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#t9","kind":"term","title":"상감 기법","text":"그릇 표면에 무늬를 파내고 그 자리를 다른 색의 흙으로 메워 무늬를 내는 기법입니다. 고려 상감 청자에 쓰였습니다.","keywords":["상감 기법"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#f0","kind":"faq","title":"고려의 삼사와 조선의 삼사는 같은 기구인가요?","text":"이름만 같고 하는 일은 다릅니다. 고려의 삼사는 화폐와 곡식의 출납·회계를 맡았고, 조선의 삼사(사헌부·사간원·홍문관)는 언론과 감찰로 권력을 견제하였습니다. 고려에서 언론·감찰을 맡은 것은 어사대와 중서문하성의 낭사(대간)입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#f1","kind":"faq","title":"팔만대장경을 만든다고 정말 몽골을 막을 수 있다고 믿었나요?","text":"당시 사람들은 부처의 힘으로 나라를 지킨다는 호국 불교 신앙을 가지고 있었습니다. 동시에 대장경을 새기는 큰 사업은 온 나라의 마음을 하나로 모아 항쟁 의지를 다지는 역할을 하였습니다. 그 결과 팔만대장경은 오늘날 정확하고 정교한 대장경으로 인정받는 세계적인 문화유산이 되었습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#f2","kind":"faq","title":"무신 정권 때 왕은 무엇을 했나요?","text":"왕은 있었지만 실권이 거의 없었습니다. 최충헌은 마음에 들지 않는 왕을 몰아내고 새 왕을 세우기도 하였습니다. 나라의 중요한 일은 교정도감·정방 같은 무신 정권의 기구에서 결정되었습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#m0","kind":"mistake","title":"자주 하는 실수","text":"서희와 강감찬을 바꾸는 실수 — 1차 침입(993) 때 외교 담판은 서희, 3차 침입 때 귀주 대첩(1019)은 강감찬입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#m1","kind":"mistake","title":"자주 하는 실수","text":"의천과 지눌의 사상을 바꾸는 실수 — 의천은 천태종·교관겸수(교종 중심), 지눌은 수선사 결사·정혜쌍수·돈오점수(선종 중심)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-04#m2","kind":"mistake","title":"자주 하는 실수","text":"팔만대장경을 금속 활자로 찍은 것으로 아는 실수 — 팔만대장경은 나무판(목판)이고, 금속 활자본은 『직지』입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-04","grade":"a"},
{"id":"hist-a-korea-05","kind":"unit","title":"조선 전기","text":"조선 건국부터 왜란·호란까지 통치 체제의 정비와 사림의 성장, 세종 대 문화, 두 전쟁의 흐름을 정리합니다. 조선의 건국 과정과 태종·세종·세조·성종의 체제 정비를 설명할 수 있다. 의정부와 6조, 삼사, 8도와 과거 제도로 이루어진 조선의 통치 체제를 설명할 수 있다. 훈민정음 창제와 세종 대의 과학 기술·편찬 사업을 정리할 수 있다. 사림의 성장과 사…","keywords":["6조 직계제","의정부 서사제","경국대전","삼사","훈민정음","사림","사화","붕당","서원","중립 외교"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#c0","kind":"concept","title":"조선의 건국과 태종·세종·세조·성종","text":"조선의 건국: 고려 말 위화도 회군(1388)으로 실권을 잡은 이성계는 정도전 등 혁명파 신진 사대부와 함께 과전법(1391)을 실시해 경제 기반을 마련하고, 1392년 조선을 세웠습니다. 1394년에는 도읍을 한양으로 옮겼습니다. 정도전은 『조선경국전』을 지어 백성을 나라의 근본으로 ","keywords":["6조 직계제","의정부 서사제"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#c1","kind":"concept","title":"조선의 통치 체제와 과거 제도","text":"중앙 정치 기구 — 권력이 한곳에 쏠리지 않도록 서로 견제하게 짜였습니다. 기구 · 하는 일 의정부 · 최고 정무 기구. 영의정·좌의정·우의정 세 정승이 국정 총괄 6조 · 이조(인사)·호조(재정)·예조(의례·교육·외교)·병조(국방)·형조(법률)·공조(건설) 승정원 · 왕명 출납(왕의 ","keywords":["삼사"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#c2","kind":"concept","title":"훈민정음 창제와 과학 기술·편찬 사업","text":"훈민정음 — 세종은 백성이 쉽게 익혀 쓸 수 있는 글자를 만들고자 1443년 훈민정음을 창제하고 1446년 반포하였습니다. \"백성을 가르치는 바른 소리\"라는 뜻입니다. 자음은 소리 내는 기관의 모양을 본떠, 모음은 하늘(·)·땅(ㅡ)·사람(ㅣ)을 본떠 만든 과학적인 글자입니다. 『용비어","keywords":["훈민정음"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#c3","kind":"concept","title":"사림의 성장과 사화, 붕당의 형성","text":"15세기 후반 조선 정치에는 두 세력이 맞섰습니다. 구분 · 훈구 · 사림 출신 · 세조의 집권을 도운 공신 중심 · 지방의 중소 지주, 길재·김종직의 학통 기반 · 고위 관직과 많은 토지 · 향촌 사회, 성리학 성향 · 중앙 집권, 부국강병 · 왕도 정치, 도덕과 의리 성종이 훈구를 ","keywords":["삼사","사림","사화","붕당"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#c4","kind":"concept","title":"임진왜란과 병자호란","text":"임진왜란(1592~1598) 전국을 통일한 일본의 도요토미 히데요시가 대군을 보내 1592년 쳐들어왔습니다. 부산진과 동래성이 함락되고, 신립이 충주 탄금대에서 패하자 선조는 의주로 피란하였습니다. 수군의 승리: 이순신이 이끄는 수군이 옥포 해전에서 첫 승리를 거두고, 한산도 대첩(15","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t0","kind":"term","title":"6조 직계제","text":"6조가 의정부를 거치지 않고 왕에게 직접 보고하는 제도입니다. 태종과 세조가 왕권을 강화하려고 실시하였습니다.","keywords":["6조 직계제"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t1","kind":"term","title":"의정부 서사제","text":"6조의 일을 의정부의 세 정승이 먼저 심의한 뒤 왕에게 올리는 제도입니다. 세종이 실시하여 왕권과 신권의 조화를 꾀하였습니다.","keywords":["의정부 서사제"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t2","kind":"term","title":"경국대전","text":"세조 때 편찬을 시작해 성종 때 완성·반포한 조선의 기본 법전입니다.","keywords":["경국대전"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t3","kind":"term","title":"삼사","text":"조선의 사헌부(감찰)·사간원(간쟁)·홍문관(경연·자문)을 함께 이르는 말입니다. 언론으로 권력의 독점을 막았습니다.","keywords":["삼사"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t4","kind":"term","title":"훈민정음","text":"세종이 1443년 창제하고 1446년 반포한 우리 글자입니다. \"백성을 가르치는 바른 소리\"라는 뜻입니다.","keywords":["훈민정음"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t5","kind":"term","title":"사림","text":"지방에서 성리학을 공부하며 성장한 양반 세력입니다. 성종 때 중앙에 진출해 훈구와 맞섰고, 선조 때 정치를 주도하였습니다.","keywords":["사림"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t6","kind":"term","title":"사화","text":"사림이 훈구 등 반대 세력에게 화를 입은 사건입니다. 무오·갑자·기묘·을사사화가 있습니다.","keywords":["사화"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t7","kind":"term","title":"붕당","text":"학문과 정치적 견해를 같이하는 양반들이 모인 정치 집단입니다. 선조 때 동인과 서인으로 처음 나뉘었습니다.","keywords":["붕당"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t8","kind":"term","title":"서원","text":"뛰어난 유학자의 제사를 지내고 학생을 가르친 사립 교육 기관입니다. 사림의 근거지가 되었습니다. 예: 백운동 서원","keywords":["서원"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#t9","kind":"term","title":"중립 외교","text":"광해군이 명과 후금 사이에서 어느 한쪽에 치우치지 않고 실리를 챙긴 외교입니다.","keywords":["중립 외교"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#f0","kind":"faq","title":"훈구와 사림은 모두 양반인데 무엇이 달랐나요?","text":"둘 다 성리학을 공부한 양반이지만 기반과 생각이 달랐습니다. 훈구는 세조의 집권을 도운 공신 중심으로, 중앙의 높은 관직과 많은 토지를 가졌습니다. 사림은 지방의 중소 지주 출신으로, 도덕과 의리를 중시하는 왕도 정치를 내세우며 훈구의 권력 독점과 비리를 비판하였습니다.","keywords":["사림"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#f1","kind":"faq","title":"임진왜란 때 이순신 장군의 해전 승리가 왜 그렇게 중요했나요?","text":"일본군은 육지로 빠르게 북쪽까지 올라왔지만, 군량과 무기를 바닷길로 보급받아야 했습니다. 이순신이 남해의 제해권을 지키자 일본군은 서해를 돌아 보급받는 계획이 막혀 더 나아가지 못하였습니다. 또 곡창 지대인 전라도를 지킬 수 있어 조선이 전쟁을 이어 갈 힘이 되었습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#f2","kind":"faq","title":"동인과 서인은 왜 나뉘었나요?","text":"선조 때 정권을 잡은 사림 안에서, 인사권을 가진 이조 전랑 자리를 누가 맡을지와 척신 정치의 잔재를 어떻게 청산할지를 두고 의견이 갈렸습니다. 김효원을 지지한 쪽이 동인, 심의겸을 지지한 쪽이 서인이 되었습니다(1575). 동인은 뒤에 다시 남인과 북인으로 나뉘었습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#m0","kind":"mistake","title":"자주 하는 실수","text":"태종·세조의 6조 직계제와 세종의 의정부 서사제를 바꾸는 실수 — 왕권을 강하게 한 왕(태종·세조)이 6조 직계제입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#m1","kind":"mistake","title":"자주 하는 실수","text":"사화의 순서를 헷갈리는 실수 — 무오(1498)·갑자(1504)는 연산군, 기묘(1519)는 중종, 을사(1545)는 명종입니다. \"무갑기을\"로 기억하세요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-05#m2","kind":"mistake","title":"자주 하는 실수","text":"정묘호란과 병자호란의 결과를 바꾸는 실수 — 정묘호란(1627)은 후금과 형제 관계, 병자호란(1636)은 청과 군신 관계입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-05","grade":"a"},
{"id":"hist-a-korea-06","kind":"unit","title":"조선 후기","text":"왜란과 호란 뒤의 수취 제도 개편, 붕당 정치의 변질과 영조·정조의 탕평 정치, 세도 정치와 농민 봉기, 경제·신분·사상·문화의 변화를 흐름에 따라 정리합니다. 영정법·대동법·균역법이 각각 무엇을 어떻게 바꾸었는지 비교할 수 있습니다. 예송과 환국을 거치며 붕당 정치가 변질된 과정과 영조·정조의 탕평 정치를 설명할 수 있습니다. 세도 정치 아래 삼정의 문…","keywords":["대동법","영정법","균역법","공인","예송","환국","탕평책","세도 정치","삼정","공명첩"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#c0","kind":"concept","title":"전쟁 뒤 수취 제도의 개편","text":"임진왜란(1592)과 병자호란(1636)을 겪은 뒤 농토는 황폐해지고 나라 살림은 바닥났습니다. 정부는 농민 생활을 안정시키고 재정을 다시 세우기 위해 세금 제도를 차례로 고쳤습니다. 조선의 세금은 크게 전세(토지세), 공납(특산물), 역(군역·요역) 세 가지였는데, 하나씩 손을 보았습","keywords":["대동법","영정법","균역법"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#c1","kind":"concept","title":"붕당 정치의 변질: 예송과 환국","text":"선조 때 사림이 동인과 서인으로 나뉘며 시작된 붕당 정치는, 처음에는 서로 견제하고 비판하며 여론을 모으는 장점이 있었습니다. 그러나 17세기 후반부터 성격이 크게 바뀌었습니다. 예송(현종 때) — 왕실의 상복을 얼마 동안 입을지를 두고 서인과 남인이 벌인 논쟁입니다. 겉으로는 예법 문","keywords":["예송","환국"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#c2","kind":"concept","title":"영조와 정조의 탕평 정치","text":"탕평은 \"어느 쪽에도 치우치지 않는다\"는 뜻입니다. 붕당 사이의 다툼을 누그러뜨리고 왕권을 강화하려는 정치를 탕평책이라고 합니다. 영조(재위 1724~1776) 탕평을 지지하는 인물을 고르게 등용하고, 성균관 입구에 탕평비(1742)를 세웠습니다. 붕당의 근거지가 된 서원을 크게 정리하","keywords":["균역법","탕평책"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#c3","kind":"concept","title":"세도 정치와 농민 봉기","text":"정조가 세상을 떠나고 어린 순조가 즉위하자, 왕의 외척 등 소수 가문이 권력을 잡았습니다. 이렇게 몇몇 가문이 나라를 좌우한 정치를 세도 정치라고 합니다. 순조·헌종·철종 3대 60여 년 동안 안동 김씨·풍양 조씨 같은 가문이 비변사를 장악하고 주요 관직을 차지하였습니다. 벼슬을 돈으로","keywords":["세도 정치","삼정"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#c4","kind":"concept","title":"경제 변화와 신분제의 동요","text":"농업 — 논에 바로 씨를 뿌리던 방식 대신, 모판에서 키운 모를 옮겨 심는 모내기법(이앙법)이 전국으로 퍼졌습니다. 김매기 일손이 크게 줄고, 벼를 거둔 논에 보리를 심는 이모작도 가능해졌습니다. 일손이 덜 들게 되자 한 사람이 더 넓은 땅을 경작하는 광작이 나타났고, 인삼·담배·면화 ","keywords":["대동법","공인"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#c5","kind":"concept","title":"실학과 서민 문화, 천주교와 동학","text":"실학 — 성리학이 현실 문제를 풀지 못한다고 보고, 실제 생활에 도움이 되는 학문을 추구한 흐름입니다. 갈래 · 학자 · 주장·저술 농업 중심 개혁론(중농학파) · 유형원 · 『반계수록』, 신분에 따라 토지를 나누어 주자는 균전론 · 이익 · 『성호사설』, 최소한의 토지(영업전) 매매를","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t0","kind":"term","title":"대동법","text":"집집마다 특산물로 내던 공납을 토지 결수에 따라 쌀(1결당 12두)·베·동전으로 내게 한 제도입니다. 1608년 경기도에서 시작해 1708년 전국으로 확대되었습니다.","keywords":["대동법"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t1","kind":"term","title":"영정법","text":"1635년 인조 때 풍흉에 관계없이 전세를 토지 1결당 쌀 4~6두로 고정한 제도입니다.","keywords":["영정법"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t2","kind":"term","title":"균역법","text":"1750년 영조 때 군포를 1년에 2필에서 1필로 줄인 제도입니다. 모자란 재정은 결작·선무군관포·어염세 등으로 보충하였습니다.","keywords":["균역법"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t3","kind":"term","title":"공인","text":"대동법 실시 뒤 관청에서 돈이나 쌀을 받아 필요한 물품을 사서 납품한 상인입니다. 상업 발달을 이끌었습니다.","keywords":["공인"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t4","kind":"term","title":"예송","text":"현종 때 왕실의 상복 입는 기간을 두고 서인과 남인이 벌인 논쟁입니다(기해예송 1659, 갑인예송 1674).","keywords":["예송"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t5","kind":"term","title":"환국","text":"숙종 때 집권 붕당이 한꺼번에 바뀐 일입니다. 경신환국(1680), 기사환국(1689), 갑술환국(1694)이 대표적입니다.","keywords":["환국"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t6","kind":"term","title":"탕평책","text":"붕당 사이의 다툼을 누그러뜨리고 인재를 고르게 쓰려 한 영조·정조의 정책입니다.","keywords":["탕평책"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t7","kind":"term","title":"세도 정치","text":"순조·헌종·철종 3대 60여 년 동안 안동 김씨·풍양 조씨 같은 소수 가문이 권력을 독차지한 정치입니다.","keywords":["세도 정치"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t8","kind":"term","title":"삼정","text":"조선 후기 나라 재정의 바탕인 전정(토지세)·군정(군포)·환곡(곡식 대여)을 말합니다. 세도 정치 때 크게 문란해졌습니다.","keywords":["삼정"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#t9","kind":"term","title":"공명첩","text":"받는 사람의 이름 칸을 비워 둔 관직 임명장입니다. 나라가 재정을 마련하려고 팔았고, 신분 상승의 통로가 되었습니다.","keywords":["공명첩"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#f0","kind":"faq","title":"대동법은 좋은 제도인데 왜 전국에 퍼지는 데 100년이나 걸렸나요?","text":"대동법은 가진 땅이 많을수록 더 많이 내는 구조라 땅을 많이 가진 양반 지주들의 반대가 컸습니다. 그래서 1608년 경기도에서 시작한 뒤 강원도·충청도·전라도·경상도·황해도로 지역을 하나씩 넓혀 갔고, 1708년에야 평안도·함경도를 뺀 전국에서 시행되었습니다.","keywords":["대동법"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#f1","kind":"faq","title":"붕당 정치와 세도 정치는 무엇이 다른가요?","text":"붕당 정치는 학문적·정치적 입장이 다른 여러 집단이 서로 견제하며 정권을 다툰 정치입니다. 세도 정치는 그런 견제마저 사라지고 왕의 외척 등 몇몇 가문이 권력을 독차지한 정치입니다. 붕당 정치에는 그래도 여론과 비판의 통로가 있었지만, 세도 정치에서는 그것이 막혀 부정부패가 심해졌습니다.","keywords":["세도 정치"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#f2","kind":"faq","title":"영조와 정조의 정책이 자꾸 헷갈려요.","text":"영조는 \"줄이고 정리한\" 왕으로 기억해 보십시오. 군포를 줄이고(균역법), 서원을 정리하고, 이조 전랑의 권한을 줄였습니다. 탕평비도 영조입니다. 정조는 \"새로 세운\" 왕입니다. 규장각·장용영·수원 화성을 새로 만들고, 신해통공으로 상업의 문을 열었습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#f3","kind":"faq","title":"실학은 왜 실제 정책으로 크게 이어지지 못했나요?","text":"실학자 상당수가 권력에서 밀려난 남인이나 서얼 등이어서 정책을 직접 펼칠 자리에 있지 않았습니다. 또 정조가 세상을 떠난 뒤 세도 정치가 시작되면서 개혁의 동력이 약해졌습니다. 그러나 실학의 생각은 뒤에 개화사상으로 이어졌습니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#m0","kind":"mistake","title":"자주 하는 실수","text":"대동법(공납)과 균역법(군역), 영정법(전세)을 섞는 실수 — 각 제도가 어느 세금을 고쳤는지부터 짝지어 기억합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#m1","kind":"mistake","title":"자주 하는 실수","text":"신해통공으로 모든 시전 상인의 특권이 없어졌다고 아는 실수 — 육의전의 금난전권은 남겨 두었습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-06#m2","kind":"mistake","title":"자주 하는 실수","text":"조선 후기에 양반 수가 줄었다고 생각하는 실수 — 공명첩·납속·족보 위조 등으로 양반 수는 오히려 크게 늘었습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-06","grade":"a"},
{"id":"hist-a-korea-07","kind":"unit","title":"개항과 대한 제국","text":"흥선 대원군의 정책과 양요, 강화도 조약과 개화 정책, 임오군란·갑신정변, 동학 농민 운동과 갑오·을미개혁, 독립 협회와 대한 제국, 국권 피탈과 국권 수호 운동까지의 흐름을 정리합니다. 흥선 대원군의 개혁 정치와 통상 수교 거부 정책, 병인양요·신미양요를 설명할 수 있습니다. 강화도 조약의 불평등한 성격과 개화 정책, 임오군란·갑신정변의 원인과 결과를 …","keywords":["통상 수교 거부 정책","양요","강화도 조약","최혜국 대우","위정척사","집강소","군국기무처","헌의 6조","구본신참","을사늑약"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#c0","kind":"concept","title":"흥선 대원군의 정책과 양요","text":"1863년 어린 고종이 즉위하자 아버지 흥선 대원군이 실권을 잡았습니다. 안으로는 세도 정치로 무너진 왕권을 다시 세우고, 밖으로는 서양 세력의 접근을 막는 것이 과제였습니다. 왕권 강화와 민생 안정 세도 가문을 몰아내고 인재를 고루 등용하였습니다. 세도 가문의 권력 기반이던 비변사를 ","keywords":["양요"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#c1","kind":"concept","title":"강화도 조약과 개화 정책","text":"1873년 흥선 대원군이 물러나고 고종이 직접 나라를 다스리게 되면서 통상을 거부하던 분위기가 바뀌었습니다. 이때 일본이 군함 운요호를 강화도 앞바다에 보내 충돌을 일으키고(1875), 이를 구실로 조약을 강요하였습니다. 강화도 조약(조일 수호 조규, 1876) — 우리나라가 맺은 최초","keywords":["강화도 조약"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#c2","kind":"concept","title":"임오군란과 갑신정변","text":"임오군란(1882) — 신식 군대 별기군에 비해 차별을 받던 구식 군인들이 일으킨 봉기입니다. 밀린 급료로 받은 쌀에 겨와 모래가 섞여 있자 분노가 터졌고, 개화 정책과 일본에 불만을 품은 도시 하층민도 합세하였습니다. 군인들은 일본 공사관을 공격하였고, 흥선 대원군이 잠시 다시 권력을","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#c3","kind":"concept","title":"동학 농민 운동과 갑오·을미개혁","text":"동학 농민 운동(1894) 고부 봉기(1월): 고부 군수 조병갑의 횡포(만석보 물세 등)에 맞서 전봉준이 농민을 이끌고 일어났습니다. 1차 봉기(3~5월): 정부가 봉기 참여자를 탄압하자 농민군이 다시 일어나 \"보국안민, 제폭구민\"을 내걸고 황토현·황룡촌에서 관군을 이기고 전주성을 점령","keywords":["집강소"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#c4","kind":"concept","title":"독립 협회와 대한 제국","text":"독립 협회(1896~1898) 아관 파천으로 러시아 등 열강이 이권을 빼앗아 가자, 미국에서 돌아온 서재필이 독립신문(1896, 최초의 민간 신문, 한글판·영문판)을 펴내고 개혁적 관료·지식인과 함께 독립 협회를 만들었습니다. 자주 국권: 영은문 자리에 독립문을 세우고, 열강의 이권 침","keywords":["헌의 6조"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#c5","kind":"concept","title":"국권 피탈 과정과 국권 수호 운동","text":"국권 피탈 과정 — 일본은 러일 전쟁(1904)을 일으키고 단계적으로 대한 제국의 주권을 빼앗았습니다. 해 · 조약·사건 · 빼앗긴 것 1904 · 한일 의정서 · 군사적 요지를 마음대로 쓸 권리 1904 · 제1차 한일 협약 · 일본이 추천한 고문이 재정·외교에 간섭(고문 정치) 19","keywords":["을사늑약"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t0","kind":"term","title":"통상 수교 거부 정책","text":"흥선 대원군이 서양 나라와 통상하고 국교를 맺는 것을 거부한 정책입니다. 신미양요 뒤 척화비를 세워 의지를 밝혔습니다.","keywords":["통상 수교 거부 정책"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t1","kind":"term","title":"양요","text":"서양 세력이 일으킨 난리라는 뜻으로, 프랑스가 침략한 병인양요(1866)와 미국이 침략한 신미양요(1871)를 말합니다.","keywords":["양요"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t2","kind":"term","title":"강화도 조약","text":"1876년 일본과 맺은 우리나라 최초의 근대적 조약입니다. 해안 측량권·영사 재판권 등을 담은 불평등 조약입니다.","keywords":["강화도 조약"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t3","kind":"term","title":"최혜국 대우","text":"조약을 맺은 상대국이 다른 나라에 준 가장 좋은 대우를 자기 나라에도 똑같이 주도록 하는 것입니다. 1882년 조미 수호 통상 조약에서 처음 인정하였습니다.","keywords":["최혜국 대우"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t4","kind":"term","title":"위정척사","text":"바른 것(성리학 질서)을 지키고 사악한 것(서양 문물·일본)을 물리치자는 유생들의 사상과 운동입니다.","keywords":["위정척사"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t5","kind":"term","title":"집강소","text":"동학 농민군이 전주 화약 뒤 전라도 각지에 설치하여 폐정 개혁을 실천한 기구입니다.","keywords":["집강소"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t6","kind":"term","title":"군국기무처","text":"1894년 1차 갑오개혁을 주도한 개혁 추진 기구입니다. 과거제·신분제 폐지 등을 의결하였습니다.","keywords":["군국기무처"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t7","kind":"term","title":"헌의 6조","text":"1898년 독립 협회가 관민 공동회에서 결의한 개혁안입니다.","keywords":["헌의 6조"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t8","kind":"term","title":"구본신참","text":"옛것을 근본으로 삼고 새것을 참고한다는 뜻으로, 대한 제국 광무개혁의 원칙입니다.","keywords":["구본신참"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#t9","kind":"term","title":"을사늑약","text":"1905년 일본이 강제로 맺게 한 조약으로, 대한 제국의 외교권을 빼앗고 통감부를 두었습니다. 강요된 조약이라는 뜻에서 \"늑약\"이라고 부릅니다.","keywords":["을사늑약"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#f0","kind":"faq","title":"병인양요와 신미양요가 자꾸 헷갈려요.","text":"순서와 나라를 묶어서 기억하십시오. 병인양요(1866) — 프랑스, 신미양요(1871) — 미국입니다. 병인양요는 천주교 탄압(병인박해)이, 신미양요는 제너럴셔먼호 사건이 구실이었습니다. 정족산성의 양헌수는 병인양요, 광성보의 어재연은 신미양요입니다.","keywords":["양요"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#f1","kind":"faq","title":"을사늑약은 왜 \"조약\"이 아니라 \"늑약\"이라고 하나요?","text":"\"늑(勒)\"은 억지로 한다는 뜻입니다. 일본은 군대로 궁궐을 둘러싸고 대신들을 위협하여 조약을 맺게 했고, 황제의 정식 비준 절차도 거치지 않았습니다. 그래서 정상적인 조약이 아니라 강요된 조약이라는 뜻으로 \"늑약\"이라고 부릅니다.","keywords":["을사늑약"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#f2","kind":"faq","title":"갑신정변, 갑오개혁, 을미개혁은 무엇이 다른가요?","text":"갑신정변(1884)은 급진 개화파가 정변으로 권력을 잡고 개혁하려다 3일 만에 실패한 사건입니다. 갑오개혁(1894~1895)은 정부가 군국기무처 등을 통해 실제로 시행한 개혁으로 신분제 폐지·과거제 폐지가 핵심입니다. 을미개혁(1895)은 을미사변 뒤의 개혁으로 단발령·태양력 사용이 대표적입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#m0","kind":"mistake","title":"자주 하는 실수","text":"병인양요(1866, 프랑스)와 신미양요(1871, 미국)의 순서와 나라를 바꾸어 기억하는 실수 — \"병인이 먼저, 프랑스\"로 묶어 둡니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#m1","kind":"mistake","title":"자주 하는 실수","text":"단발령·태양력을 갑오개혁의 내용으로 아는 실수 — 둘 다 을미사변 뒤의 을미개혁(1895)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-07#m2","kind":"mistake","title":"자주 하는 실수","text":"군대 해산을 을사늑약 때의 일로 아는 실수 — 을사늑약(1905)으로는 외교권을, 한일 신협약(1907) 때 군대를 빼앗겼습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-07","grade":"a"},
{"id":"hist-a-korea-08","kind":"unit","title":"일제 강점기와 독립운동","text":"일제의 식민 통치와 경제 수탈이 시기별로 어떻게 바뀌었는지, 그리고 3·1 운동과 대한민국 임시 정부, 무장 투쟁·의열 투쟁, 실력 양성 운동과 신간회, 민족 문화 수호와 건국 준비로 이어진 독립운동의 흐름을 정리합니다. 식민 통치 방식(무단 통치, 이른바 \"문화 통치\", 민족 말살 통치)과 경제 수탈 정책을 시기별로 구별할 수 있습니다. 3·1 운동의 …","keywords":["무단 통치","이른바 \"문화 통치\"","민족 말살 통치","토지 조사 사업","산미 증식 계획","대한민국 임시 정부","의열단","한인 애국단","신간회","한국광복군"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#c0","kind":"concept","title":"식민 통치 방식의 시기별 변화","text":"1910년 국권을 빼앗은 일제는 조선 총독부를 두고 한국을 다스렸습니다. 총독은 일본군 대장 출신이 맡아 입법·사법·행정·군사권을 모두 쥐었습니다. 통치 방식은 시기에 따라 바뀌었지만, 목적은 언제나 한국을 일본의 이익을 위해 지배하는 것이었습니다. 시기 · 통치 방식 · 주요 내용 1","keywords":["무단 통치","이른바 \"문화 통치\""],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#c1","kind":"concept","title":"식민지 경제 수탈","text":"일제의 경제 정책도 통치 방식과 함께 시기별로 바뀌었습니다. 1910년대: 토지와 회사 장악 토지 조사 사업(1910~1918): 정해진 기간 안에 땅 주인이 직접 신고해야 소유권을 인정하는 기한부 신고제로 진행하였습니다. 신고하지 못한 땅, 마을 공유지, 왕실·관청 소유지 등은 총독부","keywords":["토지 조사 사업","산미 증식 계획"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#c2","kind":"concept","title":"3·1 운동과 대한민국 임시 정부","text":"배경 — 제1차 세계 대전 뒤 미국 대통령 윌슨이 내세운 민족 자결주의(각 민족이 자기 운명을 스스로 결정한다), 도쿄의 조선 유학생들이 발표한 2·8 독립 선언(1919), 고종의 갑작스러운 서거가 겹치며 독립의 열망이 높아졌습니다. 전개 — 1919년 3월 1일 종교계 인사 등 민족","keywords":["대한민국 임시 정부"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#c3","kind":"concept","title":"무장 독립 전쟁과 의열 투쟁","text":"만주의 무장 독립 전쟁 봉오동 전투(1920.6): 홍범도의 대한 독립군 등이 봉오동에서 일본군을 크게 물리쳤습니다. 청산리 전투(1920.10): 김좌진의 북로 군정서와 홍범도의 대한 독립군 등이 백운평·어랑촌 등에서 6일 동안 일본군과 싸워 크게 이겼습니다. 독립군 최대의 승리로 꼽","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#c4","kind":"concept","title":"실력 양성 운동과 신간회, 학생·대중 운동","text":"실력 양성 운동 — 경제·교육의 힘을 길러 독립의 바탕을 마련하자는 운동입니다. 물산 장려 운동: 1920년 평양에서 조만식 등이 시작해 1923년 전국으로 퍼졌습니다. \"조선 사람 조선 것\" 등을 내걸고 우리 상품을 쓰자고 하였습니다. 그러나 상품값이 오르고, 사회주의자들에게 \"자본가","keywords":["신간회"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#c5","kind":"concept","title":"민족 문화 수호 운동과 한국광복군, 건국 준비","text":"우리말 지키기 — 조선어 연구회(1921)는 한글날의 시초인 가갸날을 정하고 잡지 『한글』을 펴냈습니다. 이를 이은 조선어 학회(1931)는 한글 맞춤법 통일안(1933)을 만들고 표준어를 정했으며, 우리말 큰사전 편찬을 추진하였습니다. 그러나 1942년 일제가 회원들을 잡아 가둔 조선","keywords":["한국광복군"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t0","kind":"term","title":"무단 통치","text":"1910년대 일제가 헌병 경찰과 군대를 앞세워 한국인을 억누른 통치 방식입니다. 조선 태형령, 즉결 처분권 등이 대표적입니다.","keywords":["무단 통치"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t1","kind":"term","title":"이른바 \"문화 통치\"","text":"3·1 운동 뒤 1920년대에 일제가 내세운 통치 방식입니다. 보통 경찰제·한글 신문 허용 등을 내세웠지만 실제로는 감시와 탄압을 강화하고 민족을 분열시키려 한 기만적인 통치였습니다.","keywords":["이른바 \"문화 통치\""],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t2","kind":"term","title":"민족 말살 통치","text":"1930년대 후반부터 일제가 한국인을 일본인으로 만들려 한 통치입니다. 황국 신민 서사 암송, 신사 참배, 창씨개명 등을 강요하였습니다.","keywords":["민족 말살 통치"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t3","kind":"term","title":"토지 조사 사업","text":"1910~1918년 일제가 기한부 신고제로 토지 소유권을 조사한 사업입니다. 많은 땅이 총독부 소유가 되었고 농민의 경작권은 무시되었습니다.","keywords":["토지 조사 사업"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t4","kind":"term","title":"산미 증식 계획","text":"1920년대 일제가 일본의 쌀 부족을 해결하려고 한국에서 쌀 생산을 늘리려 한 정책입니다. 늘어난 양보다 많은 쌀이 일본으로 실려 갔습니다.","keywords":["산미 증식 계획"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t5","kind":"term","title":"대한민국 임시 정부","text":"3·1 운동을 계기로 1919년 상하이에서 수립된, 민주 공화제를 채택한 우리 역사 최초의 정부입니다.","keywords":["대한민국 임시 정부"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t6","kind":"term","title":"의열단","text":"1919년 김원봉이 만든 단체로, 일제의 기관을 파괴하고 요인을 처단하는 의열 투쟁을 벌였습니다.","keywords":["의열단"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t7","kind":"term","title":"한인 애국단","text":"1931년 김구가 상하이에서 만든 단체로, 이봉창·윤봉길 의거를 일으켰습니다.","keywords":["한인 애국단"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t8","kind":"term","title":"신간회","text":"1927년 비타협적 민족주의자와 사회주의자가 함께 만든 일제 강점기 최대의 합법 항일 단체입니다.","keywords":["신간회"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#t9","kind":"term","title":"한국광복군","text":"1940년 대한민국 임시 정부가 충칭에서 창설한 정규군입니다.","keywords":["한국광복군"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#f0","kind":"faq","title":"3·1 운동은 독립을 이루지 못했는데 왜 그렇게 중요하게 배우나요?","text":"3·1 운동으로 곧바로 독립하지는 못했지만, 신분·지역·종교를 넘어 온 민족이 독립 의지를 보여 주었습니다. 그 결과 대한민국 임시 정부가 세워졌고, 일제는 통치 방식을 바꿀 수밖에 없었으며, 이후 독립운동이 여러 방향으로 활발해졌습니다. 오늘날 대한민국 헌법도 3·1 운동 정신을 계승한다고 밝히고 있습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#f1","kind":"faq","title":"임시 정부는 왜 나라 밖 상하이에 세웠나요?","text":"국내에서는 일제의 감시와 탄압 때문에 정부를 운영할 수 없었습니다. 상하이에는 여러 나라가 관리하는 조계 지역이 있어 일제의 손길이 상대적으로 덜 미쳤고, 외교 활동을 하기에도 좋았습니다. 1932년 윤봉길 의거 뒤에는 일제의 추적을 피해 여러 도시를 옮겨 다녔습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#f2","kind":"faq","title":"의열단과 한인 애국단은 어떻게 구별하나요?","text":"만든 사람과 해로 구별하면 쉽습니다. 의열단은 1919년 김원봉이 만주 지린에서, 한인 애국단은 1931년 김구가 상하이에서 만들었습니다. 의열단은 김상옥·나석주 등이 국내 식민 기관을 공격했고, 한인 애국단은 이봉창(도쿄)·윤봉길(상하이) 의거가 대표적입니다.","keywords":["의열단","한인 애국단"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#m0","kind":"mistake","title":"자주 하는 실수","text":"1920년대 \"문화 통치\"를 일제가 통치를 부드럽게 바꾼 것으로 이해하는 실수 — 겉모습만 바꾸고 감시·탄압과 민족 분열을 강화한 기만적 통치였습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#m1","kind":"mistake","title":"자주 하는 실수","text":"신간회(1927, 민족 협동 전선)와 신민회(1907, 애국 계몽 운동 비밀 결사)를 섞는 실수 — 이름이 비슷하니 시기로 구별합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"},
{"id":"hist-a-korea-08#m2","kind":"mistake","title":"자주 하는 실수","text":"봉오동 전투를 김좌진이 이끌었다고 아는 실수 — 봉오동은 홍범도, 청산리는 김좌진과 홍범도 등이 함께 싸웠습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-a-korea","unit":"hist-a-korea-08","grade":"a"}
]);
